import assert from "node:assert/strict";
import { createRequire } from "node:module";
import { fileURLToPath } from "node:url";
const require = createRequire(new URL("../../../../frontend/package.json", import.meta.url));
const { build } = require("esbuild");
const source = new URL("../../../../frontend/src/features/project-canvas/documents/intelligent-ui/compiled-expression-cache.ts", import.meta.url);
const result = await build({ entryPoints: [fileURLToPath(source)], bundle: true, write: false, format: "esm", platform: "node", target: "es2022" });
const { createCompiledExpressionCache } = await import(`data:text/javascript;base64,${Buffer.from(result.outputFiles[0].text).toString("base64")}`);
const cache = createCompiledExpressionCache();
const environment = { state: { amount: 3 }, data: {} };
const definition = { op: "state", name: "amount" };
const compiled = await cache.compile(definition);
assert.equal(await cache.compile(structuredClone(definition)), compiled, "unchanged content reuses compiled definition");
assert.equal(compiled(environment), 3);
assert.equal(compiled({ state: { amount: 9 }, data: {} }), 9, "environment is never cached");
definition.name = "other";
assert.equal(compiled(environment), 3, "mutating author object cannot change compiled tree");
assert.notEqual(await cache.compile(definition), compiled, "changed content recompiles");
assert.throws(() => compiled({ state: {}, data: {} }), /reference.missing/);
assert.throws(() => compiled({ state: { amount: Infinity }, data: {} }), /number.finite/);
const literal = await cache.compile({ op: "literal", value: { nested: [1] } });
const first = literal(environment);
first.nested[0] = 99;
assert.deepEqual(literal(environment), { nested: [1] }, "result cannot mutate cached literal");
await assert.rejects(cache.compile({ op: "literal", value: undefined }), /value.json/);
await assert.rejects(cache.compile({ op: "missing" }), /expression.unknown/);
for (let i = 0; i < 130; i++) await cache.compile({ op: "literal", value: i });
assert.notEqual(await cache.compile({ op: "state", name: "amount" }), compiled, "LRU evicts beyond entry bound");
const refreshed = await cache.compile({ op: "state", name: "amount" });
for (let i = 0; i < 130; i++) {
  await cache.compile({ op: "literal", value: `next-${i}` });
  assert.equal(await cache.compile({ op: "state", name: "amount" }), refreshed, "hits refresh LRU position");
}
const byteCache = createCompiledExpressionCache();
const large = (index) => ({ op: "literal", value: Array.from({ length: 6 }, () => `${index}:${"x".repeat(50000)}`) });
const largeFirst = await byteCache.compile(large(0));
for (let i = 1; i < 9; i++) await byteCache.compile(large(i));
assert.notEqual(await byteCache.compile(large(0)), largeFirst, "byte budget evicts before the entry limit");
const changing = { op: "literal", value: 1 };
const pending = byteCache.compile(changing);
changing.value = 2;
assert.equal((await pending)(environment), 1, "compile owns the bytes before asynchronous hashing");
console.log("compiled expression cache: reuse, isolation, input validation, asynchronous ownership and LRU byte/count bounds passed");
